using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws;

internal sealed class OriginalErasureComparisonDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Full-half-line squared erasure comparisons", H("Full-half-line squared erasure comparisons"),
        Blocks(
            Describe.Lean(DescribeId.Create("bit-predictor-cond-exp"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.bitPredictor_condExp"),
                H("The native bit predictor is a conditional expectation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any probability law, measurable Boolean bit and measurable observation, the regular conditional singleton probability pulled back through that observation equals the conditional expectation of the bit indicator under its comap field. The native retained-forcing proof consumes this unchanged supplier."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("bit-predictor-measurable"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.bitPredictor_measurable"),
                H("Measurability of the total native predictor"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every probability law and observation, the singleton real mass of the conditional distribution is a measurable function of the observation. The native radius-zero and forcing losses consume this unchanged supplier."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("visible-conditional-pullback"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.visible_conditional_pullback"),
                H("The actual visible posterior pulls back to the same J"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every finite measurable Presentation theta, measurable visible observation o with arbitrary measurable codomain, the original visible bitPredictor evaluated at o(outputs) equals almost surely under jointLaw(theta) the conditional expectation of the original erasedBit given o composed with the visible projection. The proof uses actual condDistrib_map and the native conditional-expectation identity. TwelveStateFullErasure consumes the unchanged bridge for the complete exterior."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("map-classifier"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.mapClassifier"),
                H("A total finite cell-mass MAP choice"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any actual finite-target and finite-observation probability space with the required measurable structures, mapClassifier selects the first maximizing class in a fixed finite ordering for each observation. Zero cells and ties are included."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("map-classifier-max"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.mapClassifier_max"),
                H("Actual joint-cell maximization"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every actual finite target q, finite observation w, observed value b and target class a, cellMass(mu,q,w,b,a) is at most the cell mass at mapClassifier(mu,q,w,b). TwelveStateFutureRecovery uses it for the fixed initial future residue on J."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("cell-mass"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.cellMass"),
                H("cellMass"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any measurable source, class and observation maps, cellMass(mu,q,w,b,a) is mu(q=a and w=b), in ENNReal. The actual quotient/MAP bridge uses this same joint cell, including null cells."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("current-map-error"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.current_map_error"),
                H("current map error"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every original theta and radius, an actual finite-word classifier attains classError and maximizes each class/word cellMass. OriginalUnifilarQuotient.actual_map_pairs uses both conclusions directly. The original universal theorem remains its other live consumer."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("error-mass-formula"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.error_mass_formula"),
                H("error mass formula"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For any probability measure, measurable finite class and observation maps, and classifier m, its disagreement mass is one minus the sum over observation b of cellMass(b,m(b)). The existing mapClassifier_optimal remains its live consumer."))), DescribeRole.Theorem),
            Paragraph(Text("Fix a finite hidden alphabet H with measurable singletons and an arbitrary original Presentation theta. Use exactly OriginalLawTrimming.jointLaw(theta), denoted J, and its actual visible pushforward visibleLaw(theta), denoted P. Classes are OriginalFutureScreening.originalClass(theta,t), the existing future-profile quotient after the proved law-preserving positive-support trimming, extended measurably over original null states. No unifilarity, positive original stationary masses, ergodicity, reversibility, time reversal or exact synchronization is assumed.")),
            Paragraph(Text("For a visible integer path z, before(z)(n)=z(-n-1) and after(z)(n)=z(n+1), for every natural n. exterior(z) is the pair of these complete sequences, omitting precisely coordinate zero. leftWord(r,z)(i)=z(-r+i) and rightWord(r,z)(i)=z(i+1), for i in Fin r, in chronological order. leftObservation is (leftWord,after), retaining the entire future after zero; rightObservation is (before,rightWord), retaining the entire past before zero. At r=0 both finite words are empty, while these entire opposite half-lines remain. Each one-sided observation omits one adjacent coordinate. No forced-zero radius-zero defect is claimed.")),
            Paragraph(Text("erasedBit(z) is the real indicator of z(0)=true. bitPredictor(mu,x,o)(e) is the real mass of true in the actual total condDistrib of x given o under mu at e. fullMean, leftMean and rightMean compose these bounded conditional-probability versions under P with exterior, leftObservation and rightObservation. leftRisk and rightRisk are their respective squared differences from fullMean, integrated under P. erasureTail(theta,R) is the ENNReal sum, over all n natural, of ofReal(leftRisk(theta,R+n)) plus ofReal(rightRisk(theta,R+n)); no finiteness premise is present.")),
            Paragraph(Text("classError(theta,r) is the ENNReal infimum, over all finite-word classifiers m from (Fin r to Bool) to the trimmed future classes, of J(originalClass(theta,0) differs from m(leftWord(r))). A fixed ordering induced by Fintype.equivFin resolves MAP ties by selecting the first class maximizing the actual joint mass of class and word. Every word, including a zero-mass word, receives a class. The finite success partition proves actual MAP attainment of this infimum.")),
            Describe.Lean(DescribeId.Create("full-half-line-erasure-comparison"),
                DeclarationHandle.Create("D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/OriginalErasureComparison.full_half_line_erasure_comparison"),
                H("Universal comparisons on the selected original realization"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every such original theta and every natural r, there is a finite-word MAP classifier whose actual error at class Q0 from X[-r,-1] is classError(theta,r). The infimum error at Q(r+1) from X[1,r] equals that same classError(theta,r). Both ENNReal.ofReal(leftRisk(theta,r)) and ENNReal.ofReal(rightRisk(theta,r)) are at most classError(theta,r). The real risks are also at most the real value classError(theta,r).toReal; actual MAP attainment proves this error finite. For every natural R, erasureTail(theta,R) is at most twice the ENNReal sum of classError(theta,R+n) over natural n. The sum can be infinite.")),
                    Paragraph(Text("For every measurable observation o from integer visible paths to a pair of complete natural-indexed binary sequences, the P conditional bit predictor composed with o and the visible projection equals J's conditional expectation of erasedBit composed with the visible projection given o composed with that projection, J-almost everywhere. The proof also applies this pullback to each finite-word/full-half-line observation through the same general private pullback lemma. Thus the visible risks and every hidden-class predictor are evaluated on the same actual J and P.")),
                    Paragraph(Text("For the left comparison, screening at zero is composed with the complete visible past and with the future's tail and center bit. ScreenedBinaryPredictor gives a total measurable g(class,complete future after zero) in [0,1] whose value at the actual class is the conditional center-bit mean given class and the complete exterior. The tower property gives the full and left visible conditional means as projections of this same g. Replace the class by any classifier of the left word. The replacement is measurable in (leftWord,after); its squared error is zero on a correct class and at most one otherwise. Nested projection optimality bounds the actual left risk by the actual classifier error, then by its infimum.")),
                    Paragraph(Text("For the right comparison, use screening at r+1. The complete future beginning at r+1 screens the pair (complete past before zero,rightWord,center bit) given Q(r+1). Disintegration gives a total measurable g(class,(before,rightWord)) in [0,1] on every class/exterior pair. The complete exterior is reconstructed measurably from the right word and the entire future starting at r+1. The tower and squared-error argument therefore give the right risk bound. The actual joint stationarity identity translates Q0 and X[-r,-1] by r+1 to Q(r+1) and X[1,r], proving equality of error laws without reversing any path.")),
                    Paragraph(Text("All coordinate reconstruction arguments include Fin 0 and use the original emitted-bit clock. Null original states remain in the original path space and carry zero actual mass; predictors remain total on impossible pairs. The finite-class singleton case, reducible, periodic and nonunifilar presentations stay within the universal quantifiers. Nonnegative ENNReal summation proves the tail comparison independently of summability. Strict contraction, marked unifilar quotient dynamics and geometric summability are separate conclusions."))),
                DescribeRole.Theorem))));
}
